<?php require_once __DIR__.'/document_studio_common.php';uid();try{$pid=trim((string)($_GET['project_id']??''));project($pdo,$pid);$q=$pdo->prepare('SELECT id,template_key,name,requirement_type,description FROM requirement_document_templates WHERE is_active=1 AND(project_id IS NULL OR project_id=?) ORDER BY is_system DESC,name');$q->execute([$pid]);out(['success'=>true,'templates'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}catch(Throwable$e){out(['success'=>false,'error'=>$e->getMessage()],500);}